// Build-time PWA pieces for the web app:
//  - the iOS launch-screen <link>s, generated by tools/appart into
//    public/splash/splash.json, injected into index.html;
//  - dist/sw.js, from pwa/sw.js with this build's version and file list.
import {createHash} from 'crypto';
import fs from 'fs';
import path from 'path';

import type {Plugin} from 'vite';

function walk(dir: string, base = dir): string[] {
  return fs.readdirSync(dir, {withFileTypes: true}).flatMap(e => {
    const p = path.join(dir, e.name);
    return e.isDirectory()
      ? walk(p, base)
      : [path.relative(base, p).split(path.sep).join('/')];
  });
}

export function pwa(): Plugin {
  let outDir = 'dist';
  let root = process.cwd();
  return {
    name: 'supermatrix-pwa',
    configResolved(c) {
      root = c.root;
      outDir = path.resolve(c.root, c.build.outDir);
    },
    transformIndexHtml() {
      const file = path.join(root, 'public/splash/splash.json');
      if (!fs.existsSync(file)) return [];
      const links: {href: string; media: string}[] = JSON.parse(
        fs.readFileSync(file, 'utf8'),
      );
      return links.map(l => ({
        tag: 'link',
        attrs: {rel: 'apple-touch-startup-image', href: l.href, media: l.media},
        injectTo: 'head' as const,
      }));
    },
    closeBundle() {
      if (!fs.existsSync(outDir)) return;
      // Everything the app needs to start offline. Launch screens are only
      // read by iOS at startup, straight from the network or its own cache.
      const files = walk(outDir)
        .filter(
          f => f !== 'sw.js' && !f.startsWith('splash/') && !f.endsWith('.map'),
        )
        .sort();
      const hash = createHash('sha256');
      for (const f of files)
        hash.update(f).update(fs.readFileSync(path.join(outDir, f)));
      const version = hash.digest('hex').slice(0, 16);
      // The page as "/": many servers redirect /index.html there (see sw.js).
      const precache = files.map(f => (f === 'index.html' ? '/' : '/' + f));
      const src = fs
        .readFileSync(path.join(root, 'pwa/sw.js'), 'utf8')
        .replace('self.__VERSION__', JSON.stringify(version))
        .replace('self.__PRECACHE__', JSON.stringify(precache));
      fs.writeFileSync(path.join(outDir, 'sw.js'), src);
    },
  };
}
